package com.resourceflow.model;

import java.time.LocalDateTime;
import java.util.*;

/**
 * Output plan generated by an AllocationStrategy containing allocations and evaluated metrics.
 */
public class AllocationPlan {
    private String planId;
    private StrategyType strategyType;
    private String strategyName;
    private LocalDateTime timestamp;
    private List<AllocatedItem> items;
    private EvaluationMetrics metrics;
    private boolean feasible;
    private String notes;

    public AllocationPlan() {
        this.planId = UUID.randomUUID().toString();
        this.timestamp = LocalDateTime.now();
        this.items = new ArrayList<>();
        this.metrics = new EvaluationMetrics();
        this.feasible = true;
        this.notes = "";
    }

    public AllocationPlan(StrategyType strategyType, String strategyName, List<AllocatedItem> items) {
        this.planId = UUID.randomUUID().toString();
        this.strategyType = strategyType;
        this.strategyName = strategyName;
        this.timestamp = LocalDateTime.now();
        this.items = (items != null) ? new ArrayList<>(items) : new ArrayList<>();
        this.metrics = new EvaluationMetrics();
        this.feasible = true;
        this.notes = "";
    }

    public String getPlanId() {
        return planId;
    }

    public void setPlanId(String planId) {
        this.planId = planId;
    }

    public StrategyType getStrategyType() {
        return strategyType;
    }

    public void setStrategyType(StrategyType strategyType) {
        this.strategyType = strategyType;
    }

    public String getStrategyName() {
        return strategyName;
    }

    public void setStrategyName(String strategyName) {
        this.strategyName = strategyName;
    }

    public LocalDateTime getTimestamp() {
        return timestamp;
    }

    public void setTimestamp(LocalDateTime timestamp) {
        this.timestamp = timestamp;
    }

    public List<AllocatedItem> getItems() {
        return items;
    }

    public void setItems(List<AllocatedItem> items) {
        this.items = (items != null) ? new ArrayList<>(items) : new ArrayList<>();
    }

    public void addItem(AllocatedItem item) {
        if (item != null) {
            this.items.add(item);
        }
    }

    public Optional<AllocatedItem> getItemForRequest(String requestId) {
        return items.stream()
                .filter(i -> Objects.equals(i.getRequestId(), requestId))
                .findFirst();
    }

    public EvaluationMetrics getMetrics() {
        return metrics;
    }

    public void setMetrics(EvaluationMetrics metrics) {
        this.metrics = metrics != null ? metrics : new EvaluationMetrics();
        this.feasible = this.metrics.isFeasible();
    }

    public boolean isFeasible() {
        return feasible && (metrics == null || metrics.isFeasible());
    }

    public void setFeasible(boolean feasible) {
        this.feasible = feasible;
    }

    public String getNotes() {
        return notes;
    }

    public void setNotes(String notes) {
        this.notes = notes == null ? "" : notes.trim();
    }
}
